    $auth = HubOwnerAuthService::openExisting($db); $auth->provisionInitial('art', $password, $now); $session = $auth->login('art', $password, true, 'm17-browser', $now); $control = HubControlPlaneService::openExisting($db); $browser = m17_browser($session['sessionToken'], $session['csrfToken']);

    $document = m17_control($control, 'POST', '/api/v1/control/school/documents', $browser, ['schemaVersion' => 1, 'projectId' => $project, 'subject' => 'ขออนุมัติจัดกิจกรรมวันวิทยาศาสตร์', 'details' => 'ขออนุมัติจัดกิจกรรมเพื่อส่งเสริมการเรียนรู้ของนักเรียน โดยรายละเอียดงบประมาณจะกรอกตามข้อมูลจริง', 'idempotencyKey' => 'm17-document-0001']);
    m17_assert($document['status'] === 201, 'school document route accepts valid input'); $documentBody = json_decode($document['body'], true, 32, JSON_THROW_ON_ERROR); m17_assert(($documentBody['task']['state'] ?? null) === 'COMPLETED', 'school document task completes'); m17_assert(($documentBody['pipeline']['classification'] ?? null) === 'MEMORANDUM_REQUEST', 'document classification is durable'); m17_assert(($documentBody['pipeline']['templateId'] ?? null) === 'school-memorandum-v1', 'document template is durable');
