    $duplicate = m17_control($control, 'POST', '/api/v1/control/school/documents', $browser, ['schemaVersion' => 1, 'projectId' => $project, 'subject' => 'ขออนุมัติจัดกิจกรรมวันวิทยาศาสตร์', 'details' => 'ขออนุมัติจัดกิจกรรมเพื่อส่งเสริมการเรียนรู้ของนักเรียน โดยรายละเอียดงบประมาณจะกรอกตามข้อมูลจริง', 'idempotencyKey' => 'm17-document-0001']); $duplicateBody = json_decode($duplicate['body'], true, 32, JSON_THROW_ON_ERROR); m17_assert($duplicate['status'] === 201 && ($duplicateBody['idempotent'] ?? false) === true && is_string($duplicateBody['artifact']['downloadUrl'] ?? null), 'school document is idempotent with artifact read-back');

