    $conversationBody = json_decode($conversation['body'], true, 32, JSON_THROW_ON_ERROR); $conversationId = $conversationBody['conversation']['conversationId'] ?? null; m17_assert($conversation['status'] === 201 && is_string($conversationId), 'universal command conversation is ready');
    $chatDocument = m17_control($control, 'POST', '/api/v1/control/conversations', $browser, ['schemaVersion' => 3, 'projectId' => $project, 'conversationId' => $conversationId, 'message' => 'สร้างบันทึกข้อความขอเบิกค่าน้ำมันไปราชการ', 'attachmentIds' => [], 'idempotencyKey' => 'm17-chat-document-0001']);
