    m17_assert($factory['status'] === 201, 'project factory route accepts valid input'); $factoryBody = json_decode($factory['body'], true, 32, JSON_THROW_ON_ERROR); $factoryProject = $factoryBody['project']['projectId'] ?? null; m17_assert(is_string($factoryProject) && $factoryProject !== $project, 'project factory creates a canonical project'); m17_assert(($factoryBody['factory']['task']['state'] ?? null) === 'COMPLETED', 'project factory task completes'); m17_assert(($factoryBody['factory']['pipeline']['mode'] ?? null) === 'PROJECT_FACTORY_SCHOOL_WEBSITE', 'project factory pipeline is durable'); m17_assert(($factoryBody['factory']['pipeline']['preview'] ?? null) === 'READY' && ($factoryBody['factory']['pipeline']['validation'] ?? null) === 'PASS' && ($factoryBody['factory']['pipeline']['releaseReadiness'] ?? null) === 'OWNER_APPROVAL', 'project factory must produce a validated preview without faking deployment'); $factoryArtifact = $factoryBody['factory']['artifact']['artifactId'] ?? null; m17_assert(is_string($factoryArtifact) && ($factoryBody['factory']['artifact']['kind'] ?? null) === 'project-preview', 'project factory creates a canonical preview artifact');
    $factoryDuplicate = m17_control($control, 'POST', '/api/v1/control/project-factory', $browser, ['schemaVersion' => 1, 'name' => 'เว็บไซต์สหกรณ์โรงเรียน M17', 'objective' => 'ให้ครูและนักเรียนดูข่าวสาร รายการสินค้า และข้อมูลการดำเนินงานของสหกรณ์ได้จากมือถือ', 'type' => 'school-website', 'idempotencyKey' => 'm17-factory-0001']); $factoryDuplicateBody = json_decode($factoryDuplicate['body'], true, 32, JSON_THROW_ON_ERROR); m17_assert($factoryDuplicate['status'] === 201 && ($factoryDuplicateBody['idempotent'] ?? false) === true && ($factoryDuplicateBody['project']['projectId'] ?? null) === $factoryProject && is_string($factoryDuplicateBody['factory']['artifact']['downloadUrl'] ?? null), 'project factory is idempotent with artifact read-back');
